document.addEventListener("DOMContentLoaded",function(){const t=document.querySelectorAll(".filter-btn"),e=document.querySelectorAll(".card-menu");t.forEach(s=>{s.addEventListener("click",function(){const s=this.getAttribute("data-category");t.forEach(t=>t.classList.remove("active")),this.classList.add("active"),e.forEach(t=>{const e=t.getAttribute("data-category");"all"===s||e===s?(t.style.opacity="0",t.style.display="block",t.offsetHeight,setTimeout(()=>{t.style.transition="opacity 0.3s ease",t.style.opacity="1"},10)):(t.style.transition="opacity 0.3s ease",t.style.opacity="0",setTimeout(()=>{t.style.display="none"},300))})})})});